B.Va=s(["Los operadores aritm\xe9ticos transforman n\xfameros.","Los operadores relacionales producen un bool.","&&, || y ! combinan o invierten condiciones.","El ternario expresa decisiones simples en una expresi\xf3n."],t.s)
B.Rr=new A.aU("Divisi\xf3n y residuo","~/ devuelve divisi\xf3n entera y % devuelve el residuo.","void main() {\n  print(10 / 3);\n  print(10 ~/ 3);\n  print(10 % 3);\n}","3.3333333333333335\n3\n1")
B.Rk=new A.aU("Validaci\xf3n compuesta","Combina requisitos utilizando operadores l\xf3gicos.","void main() {\n  const edad = 20;\n  const tieneEntrada = true;\n  final puedeEntrar = edad >= 18 && tieneEntrada;\n  print(puedeEntrar ? 'Puede entrar' : 'No puede entrar');\n}","Puede entrar")
B.XU=s([B.Rr,B.Rk],t.W)
